import React from 'react';
import { NavLink } from 'react-router-dom';

import {
  FiHome,
  FiCalendar,
  FiImage,
  FiVideo,
  FiGrid,
  FiBookOpen,
  FiClipboard,
  FiUsers,
  FiStar,
  FiAward,
  FiMessageSquare,
  FiSettings,
  FiX,
  FiLayers,
  FiFilm,
  FiHeart,
} from 'react-icons/fi';

import { useLanguage } from '../../contexts/LanguageContext';

import logo from './SC ACADEMY new.png';

const AdminSidebar = ({
  isOpen = false,
  onClose,
}) => {
  const { t } = useLanguage();

  const menuItems = [
    {
      key: 'admin.dashboard',
      name: t('admin.dashboard'),
      path: '/',
      icon: FiHome,
    },
    {
      key: 'admin.gallery',
      name: t('admin.gallery'),
      path: '/gallery',
      icon: FiImage,
    },
    {
      key: 'admin.videos',
      name: t('admin.videos'),
      path: '/videos',
      icon: FiVideo,
    },
    {
      key: 'admin.courses',
      name: t('admin.courses'),
      path: '/courses',
      icon: FiBookOpen,
    },
    {
      key: 'admin.enrollments',
      name: t('admin.enrollments'),
      path: '/enrollments',
      icon: FiClipboard,
    },
    {
      key: 'admin.schools',
      name: t('admin.schools'),
      path: '/schools',
      icon: FiLayers,
    },
    {
      key: 'admin.alumni',
      name: t('admin.alumni'),
      path: '/alumni',
      icon: FiAward,
    },
    {
      key: 'admin.charity',
      name: t('admin.charity'),
      path: '/charity',
      icon: FiHeart,
    },
    {
      key: 'admin.testimonials',
      name: t('admin.testimonials'),
      path: '/testimonials',
      icon: FiStar,
    },
    {
      key: 'admin.messages',
      name: t('admin.messages'),
      path: '/messages',
      icon: FiMessageSquare,
    },
    {
      key: 'admin.settings',
      name: t('admin.settings'),
      path: '/settings',
      icon: FiSettings,
    },
  ];

  const handleClose = () => {
    if (typeof onClose === 'function') {
      onClose();
    }
  };

  return (
    <>
      {/* Mobile Overlay */}
      {isOpen && (
        <div
          className="fixed inset-0 z-40 bg-primary-950/70 backdrop-blur-[2px] lg:hidden"
          onClick={handleClose}
          aria-hidden="true"
        />
      )}

      {/* Sidebar */}
      <aside
        className={`
          fixed top-0 left-0 z-50
          w-[250px] h-screen
          bg-primary-900 text-white
          border-r border-white/10
          shadow-xl
          transition-transform duration-300 ease-in-out
          lg:translate-x-0
          ${isOpen ? 'translate-x-0' : '-translate-x-full'}
        `}
      >
        {/* Brand Header */}
        <div className="h-[84px] px-4 flex items-center justify-between border-b border-white/10">
          <NavLink
            to="/"
            onClick={handleClose}
            className="flex items-center gap-3 min-w-0"
          >
            {/* Logo */}
            <div className="w-12 h-12 flex items-center justify-center flex-shrink-0 bg-white rounded-full p-1.5 shadow-md border-2 border-white/20 overflow-hidden transition-all duration-300 hover:border-accent-red">
              <img
                src={logo}
                alt="SC Academy Logo"
                className="w-full h-full object-contain"
              />
            </div>

            {/* Brand Text */}
            <div className="min-w-0">
              <h1 className="text-[16px] font-bold text-white leading-tight truncate">
                <span className="text-accent-redLight">SC</span> Academy
              </h1>
              <p className="text-[10px] text-white/50 uppercase tracking-[0.15em] mt-1 truncate">
                {t('admin.panel')}
              </p>
            </div>
          </NavLink>

          {/* Mobile Close */}
          <button
            type="button"
            onClick={handleClose}
            className="lg:hidden w-9 h-9 flex items-center justify-center flex-shrink-0 rounded-lg bg-white/5 text-white/60 hover:bg-status-error hover:text-white transition-all duration-200"
            aria-label="Close sidebar"
          >
            <FiX size={19} />
          </button>
        </div>

        {/* Navigation */}
        <nav
          className="px-3 pt-4 pb-5 overflow-y-auto scrollbar-thin"
          style={{ height: 'calc(100vh - 84px)' }}
        >
          {/* Management Label */}
          <div className="flex items-center gap-2 px-3 mb-2">
            <span className="w-1.5 h-1.5 bg-accent-red rounded-full flex-shrink-0" />
            <p className="text-[10px] font-bold uppercase tracking-[0.18em] text-white/40 truncate">
              {t('admin.management')}
            </p>
          </div>

          {/* Menu Items */}
          <div className="space-y-1">
            {menuItems.map((item) => {
              const Icon = item.icon;
              return (
                <NavLink
                  key={item.key}
                  to={item.path}
                  end={item.path === '/'}
                  onClick={handleClose}
                  className={({ isActive }) => `
                    relative group
                    min-h-[46px]
                    flex items-center gap-3
                    px-3 py-2
                    rounded-lg
                    text-[13px] font-medium
                    transition-all duration-200
                    ${isActive
                      ? 'bg-white text-primary-900 shadow-sm'
                      : 'text-white/60 hover:bg-white/10 hover:text-white'
                    }
                  `}
                >
                  {({ isActive }) => (
                    <>
                      {/* Active Left Line */}
                      {isActive && (
                        <span className="absolute left-0 top-1/2 -translate-y-1/2 w-[3px] h-6 bg-accent-red rounded-r-full" />
                      )}

                      {/* Icon */}
                      <div
                        className={`
                          w-8 h-8
                          flex items-center justify-center
                          rounded-lg flex-shrink-0
                          transition-all duration-200
                          ${isActive
                            ? 'bg-primary-50 text-primary-900'
                            : 'bg-white/5 text-white/40 group-hover:bg-white/10 group-hover:text-white'
                          }
                        `}
                      >
                        <Icon size={17} />
                      </div>

                      {/* Menu Name */}
                      <span className="flex-1 truncate">
                        {item.name}
                      </span>

                      {/* Active Dot */}
                      {isActive && (
                        <span className="w-1.5 h-1.5 bg-accent-red rounded-full flex-shrink-0" />
                      )}
                    </>
                  )}
                </NavLink>
              );
            })}
          </div>

          {/* Divider */}
          <div className="h-px bg-white/10 my-4 mx-2" />

          {/* System Status */}
          <div className="mx-1 p-3 bg-white/5 border border-white/10 rounded-xl">
            <div className="flex items-center gap-2">
              <div className="relative flex-shrink-0">
                <span className="block w-2 h-2 bg-status-success rounded-full" />
                <span className="absolute inset-0 w-2 h-2 bg-status-success rounded-full animate-ping opacity-50" />
              </div>
              <span className="text-[11px] font-semibold text-white">
                {t('admin.systemOnline')}
              </span>
            </div>
            <p className="text-[10px] text-white/40 mt-1.5 leading-5">
              {t('admin.administration')}
            </p>
          </div>
        </nav>
      </aside>
    </>
  );
};

export default AdminSidebar;
